begin; do $$ declare r text; begin foreach r in array array['workspace_query_owner','workspace_review_ingest_owner'] loop perform set_config('votus_review_facade.'||r,pg_has_role(current_user,r,'SET')::text,true); if not pg_has_role(current_user,r,'SET') then execute format('grant %I to %I',r,current_user); end if; end loop; end $$; set role workspace_review_ingest_owner; grant select on workspace_private.review_item_section_scope to workspace_query_owner; create policy workspace_query_owner_review_scope_select on workspace_private.review_item_section_scope for select to workspace_query_owner using(true); reset role; grant create on schema workspace_private,workspace_api to workspace_query_owner; set role workspace_query_owner; create function workspace_private.review_item_is_authorized(p_review_item_id uuid) returns boolean language sql stable security definer set search_path=pg_catalog,workspace_private,pg_temp as $$ select exists(select 1 from workspace_private.review_item_section_scope s join workspace_private.authorized_section_scopes() a on a.authorization_status='authorized' and a.distrito_code=s.distrito_code and a.seccion_code=s.seccion_code where s.review_item_id=p_review_item_id) $$; revoke all on function workspace_private.review_item_is_authorized(uuid) from public,anon,authenticated; grant execute on function workspace_private.review_item_is_authorized(uuid) to authenticated; reset role; grant select on public.review_item to workspace_query_owner; drop policy review_item_authenticated_read on public.review_item; create policy review_item_authenticated_read on public.review_item for select to authenticated using(workspace_private.review_item_is_authorized(id)); create policy workspace_query_owner_review_select on public.review_item for select to workspace_query_owner using(workspace_private.review_item_is_authorized(id)); create or replace view public.review_item_unresolved_count with (security_invoker=true) as select count(*)::integer unresolved_count from public.review_item where resolved_at is null; create index review_item_authorized_unresolved_idx on public.review_item(detected_at desc,id) where resolved_at is null and tenant_scope_state='section_scoped'; set role workspace_query_owner; create function workspace_api.review_items(p_limit integer default 50,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,workspace_private,public,pg_temp as $$ declare auth_status text; item_total bigint; items jsonb; payload jsonb; begin if p_limit is null or p_limit<0 or p_limit>100 or p_offset is null or p_offset<0 or p_offset>2000000000 then raise exception 'invalid review pagination' using errcode='22023'; end if; select min(a.authorization_status) into auth_status from workspace_private.authorized_section_scopes() a; if auth_status not in ('authorized','authorized_empty') then return jsonb_build_object('status','authorization_denied','authorization_status',auth_status,'items','[]'::jsonb,'total',0,'truncated',false,'exclusions','[]'::jsonb); end if; if auth_status='authorized_empty' then return jsonb_build_object('status','ok','authorization_status','authorized_empty','items','[]'::jsonb,'total',0,'truncated',false,'exclusions','[]'::jsonb); end if; with visible as materialized (select id,kind,severity,detected_at from public.review_item where resolved_at is null), counted as (select count(*) total from visible), page as (select * from visible order by detected_at desc,id limit p_limit offset p_offset) select counted.total,coalesce(jsonb_agg(jsonb_build_object('id',page.id,'kind',page.kind,'severity',page.severity,'detected_at',page.detected_at) order by page.detected_at desc,page.id) filter(where page.id is not null),'[]'::jsonb) into item_total,items from counted left join page on true group by counted.total; payload:=jsonb_build_object('status','ok','authorization_status','authorized','items',items,'total',item_total,'truncated',item_total>p_offset+p_limit,'exclusions',case when item_total>p_offset+p_limit then jsonb_build_array(jsonb_build_object('reason','pagination_bound','rows',item_total-p_offset-p_limit)) else '[]'::jsonb end); if octet_length(payload::text)>120000 then return jsonb_build_object('status','payload_too_large','authorization_status','authorized','items','[]'::jsonb,'total',item_total,'truncated',true,'exclusions',jsonb_build_array(jsonb_build_object('reason','payload_bound'))); end if; return payload; end $$; revoke all on function workspace_api.review_items(integer,integer) from public,anon,authenticated; grant execute on function workspace_api.review_items(integer,integer) to authenticated; reset role; revoke create on schema workspace_private,workspace_api from workspace_query_owner; do $$ begin if to_regrole('service_role') is not null then revoke all on function workspace_private.review_item_is_authorized(uuid),workspace_api.review_items(integer,integer) from service_role; end if; end $$; do $$ declare r text; begin foreach r in array array['workspace_review_ingest_owner','workspace_query_owner'] loop if current_setting('votus_review_facade.'||r,true)='false' then execute format('revoke %I from %I',r,current_user); end if; end loop; end $$; commit;
